#[test]
fn every_program_is_the_bytes_c_compiles() {
    let mut wrong = Vec::new();
    for &(dialect, expr, c) in CASES {
        let rs = match dialect {
            'b' => compile(expr),
            's' => scalc_compile(expr),
            _ => acalc_compile(expr),
        };
        match rs {
            Ok(p) if p.code() == c => {}
            other => wrong.push(format!(
                "{dialect} {expr:?}: C {c:?}, rs {:?}",
                other.map(|p| p.code().to_vec())
            )),
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

